defineConfig({
  mongodb: {
    uri: env("MONGODB_URI", { default: "mongodb://localhost:27017/?replicaSet=rs0" }),
    database: "canopy_dev_app",
  },
  keys: {
    publishable: env.list.optional("CANOPY_PUBLISHABLE_KEYS"),
    secret: env.list.optional("CANOPY_SECRET_KEYS"),
  },
  policies: { dir: "./policies" },
})

defineConfig({
    mongodb: {
      uri: env["MONGODB_URI"] ?? "mongodb://localhost:27017/?replicaSet=rs0",
      database,
      metaDatabase: `${database}_meta`,
    },
    keys: { publishable: [env["NEXT_PUBLIC_CANOPY_KEY"] ?? "pk_next_local"] },
    cors: { origins: [env["SITE_URL"] ?? "http://localhost:3000"] },
    realtime: { checkpoints: "off" },
  })

defineConfig({
      mongodb: {
        uri: options.mongoUri,
        database: options.database,
        metaDatabase: `${options.database}_meta`,
        authDatabase: `${options.database}_auth`,
      },
      publicUrl: options.publicUrl,
      masterKey,
      auth: builtin({
        emailPassword: { minPasswordLength: 10, requireEmailVerification: false },
        trustedProxies: ["127.0.0.1", "::1"],
      }),
      keys: { publishable: [options.publishableKey] },
      realtime: { checkpoints: "off" },
    })

defineConfig({
        mongodb: { uri: MONGODB_URI ?? "", ...names },
        publicUrl: url,
        masterKey: "c".repeat(48),
        auth: builtin({
          anonymous: true,
          trustedProxies: ["127.0.0.1", "::1"],
          claims: () => {
            if (failHook) throw new Error("hook down")
            return undefined
          },
        }),
        keys: { publishable: [KEY] },
        realtime: { checkpoints: "off" },
      })

defineConfig({
        mongodb: { uri: mongo, database: "sdk_fixture", metaDatabase: "sdk_fixture_meta" },
        auth: external({ jwks: { keys: [jwk] }, issuer: "iss", audience: "aud" }),
        keys: { publishable: [] },
        realtime: { checkpoints: "off" },
      })

defineConfig({
        mongodb: { uri: mongo, database: "sdk_fixture", metaDatabase: "sdk_fixture_meta" },
        auth: external({ jwks: { keys: [jwk] }, issuer: "iss", audience: "aud" }),
        keys: { publishable: [] },
        realtime: { checkpoints: "off" },
      })

