        keys: { publishable: [] },
        realtime: { checkpoints: "off" },
      })

defineConfig({
        mongodb: { uri: mongo, database: "sdk_fixture", metaDatabase: "sdk_fixture_meta" },
        auth: external({ jwks: { keys: [jwk] }, issuer: "iss", audience: "aud" }),
        keys: { publishable: ["pk"] },
        realtime: { checkpoints: "off" },
      })

defineConfig({ mongodb: { uri: mongo }, storage: { backend: {
      kind: "r2", bucket: "fixture", accessKeyId: "access", secretAccessKey: env.secret("STORAGE_KEY"), prefix: "media/",
      accountId: "0123456789abcdef0123456789abcdef", jurisdiction: "eu"
    } } })

defineConfig({ mongodb: { uri: mongo }, storage: { backend: {
      kind: "s3", bucket: "fixture", accessKeyId: "access", secretAccessKey: env.secret("STORAGE_KEY"), prefix: "media/",
      region: "us-east-1", endpoint: "https://storage.example.test", sessionToken: env.secret.optional("SESSION_TOKEN"), forcePathStyle: true
    } } })

(() => {
  let calls = 0
  return defineConfig(({ mode, command }) => {
    if (++calls !== 1) throw new Error("Config function was evaluated more than once")
    return {
      mongodb: { uri: mongo },
      environment: mode,
      masterKey: env.secret("MASTER"),
      log: { level: command === "dev" ? "debug" : "info" },
    }
  })
})()

